import asyncio


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently and return their results in input order.
    Coroutines not finished within `seconds` are cancelled and their result is None.
    Can be called repeatedly from synchronous code."""
    async def _run_all_with_deadline():
        tasks = [asyncio.create_task(c) for c in coros]
        done, pending = await asyncio.wait(tasks, timeout=seconds)
        # Cancel pending tasks
        for task in pending:
            task.cancel()
        # Await cancellation completion
        for task in pending:
            try:
                await task
            except asyncio.CancelledError:
                pass
            except Exception:
                # Ignore exceptions from cancellation
                pass
        results = []
        for task in tasks:
            if task in done:
                try:
                    results.append(task.result())
                except Exception:
                    # Propagate exceptions from finished tasks
                    raise
            else:
                results.append(None)
        return results

    loop = asyncio.get_event_loop()
    return loop.run_until_complete(_run_all_with_deadline())

